CREATE OR REPLACE FUNCTION finance_private.accountant() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog','public' AS $function$ SELECT public.account_enabled() AND EXISTS(SELECT 1 FROM public.staff_members s JOIN public.profiles u ON u.id=s.user_id WHERE s.user_id=auth.uid() AND u.banned_at IS NULL AND s.active AND 'finance'=ANY(s.perms)) $function$;
